(()=>{const token=document.querySelector('meta[name="csrf-token"]')?.content;window.MALL_CSRF_TOKEN=token;if(window.jQuery){jQuery.ajaxPrefilter(function(options,original,xhr){if(!/^(GET|HEAD|OPTIONS)$/i.test(options.type||'GET'))xhr.setRequestHeader('X-CSRF-TOKEN',token);});}document.querySelectorAll('form[method="post"]').forEach(form=>{if(!form.querySelector('[name="_csrf"]')){const input=document.createElement('input');input.type='hidden';input.name='_csrf';input.value=token;form.append(input);}});})();
